-- Jeopardy-style wording generated by Gemini, plus subject keywords used to build categories at game start.
ALTER TABLE clue
    ADD COLUMN jeopardy_clue     TEXT         NULL AFTER answer,
    ADD COLUMN jeopardy_response VARCHAR(600) NULL AFTER jeopardy_clue,
    ADD COLUMN enriched_at       TIMESTAMP    NULL,
    ADD COLUMN enrich_attempts   INT          NOT NULL DEFAULT 0,
    ADD KEY idx_clue_enrichment (enriched_at, enrich_attempts);

CREATE TABLE keyword (
    id   BIGINT      NOT NULL AUTO_INCREMENT,
    name VARCHAR(64) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_keyword_name (name)   -- default collation is case-insensitive, so "Astronomy" = "astronomy"
);

CREATE TABLE clue_keyword (
    clue_id    BIGINT NOT NULL,
    keyword_id BIGINT NOT NULL,
    PRIMARY KEY (clue_id, keyword_id),
    KEY idx_clue_keyword_keyword (keyword_id),
    CONSTRAINT fk_clue_keyword_clue    FOREIGN KEY (clue_id)    REFERENCES clue (id) ON DELETE CASCADE,
    CONSTRAINT fk_clue_keyword_keyword FOREIGN KEY (keyword_id) REFERENCES keyword (id) ON DELETE CASCADE
);
